class Solution {
  public int countEffective(int[] nums) {
    final long MOD = 1_000_000_007L;
    int n = nums.length, total = 0;
    for (int x : nums) total |= x;
    // only the bits of the overall OR matter: compress them to 0..B-1 so the table has 2^B entries, not 2^20
    int[] bitPos = new int[Integer.bitCount(total)];
    for (int b = 0, i = 0; b < 31; b++) if ((total >> b & 1) != 0) bitPos[i++] = b;
    int bits = bitPos.length, size = 1 << bits;
    int[] f = new int[size]; // f[mask] = number of elements whose bits lie within mask
    for (int x : nums) {
      int m = 0;
      for (int i = 0; i < bits; i++) if ((x >> bitPos[i] & 1) != 0) m |= 1 << i;
      f[m]++;
    }
    for (int i = 0; i < bits; i++)
      for (int mask = 0; mask < size; mask++)
        if ((mask >> i & 1) != 0) f[mask] += f[mask ^ (1 << i)];
    long[] pow2 = new long[n + 1];
    pow2[0] = 1;
    for (int i = 1; i <= n; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
    // inclusion-exclusion over the set of OR bits the remaining elements all lack
    long ans = 0;
    for (int sub = 1; sub < size; sub++) {
      long term = pow2[f[(size - 1) ^ sub]];
      ans += Integer.bitCount(sub) % 2 == 1 ? term : MOD - term;
    }
    return (int) (ans % MOD);
  }
}
